// gh-2042 AC2 — release_drift_remediate.sh: when the drift check finds a
// published release whose assets no longer match the signed SHA256SUMS, the
// run must (a) auto re-request the release-provenance job for the tag (it
// re-hashes the CURRENT assets and re-signs — the same mechanism as the AC3
// v1.0.680 remediation) and (b) page a deduplicated issue so drift never
// lingers.
//
// Behavioral tests over a stubbed `gh` (run list / api jobs / run rerun /
// issue list+create+comment), following the release_hygiene_test.dart style.
import 'dart:io';

import 'package:test/test.dart';

void main() {
  late Directory fx;
  late String bin;
  late String logPath;
  late String bodyFile;

  setUp(() {
    fx = Directory.systemTemp.createTempSync('drift-remediate-');
    bin = '${fx.path}/bin';
    Directory(bin).createSync();
    logPath = '${fx.path}/gh.log';
    bodyFile = '${fx.path}/drift.txt';
    File(bodyFile).writeAsStringSync('''
- fa-macos-arm64.tar.gz: manifest cd0eb0e1… ≠ actual 251f0c1c…
- fa-macos-arm64-mac.zip: on the release but not in the manifest
''');
    File('$bin/gh').writeAsStringSync(_ghStub);
    Process.runSync('chmod', ['+x', '$bin/gh']);
  });

  tearDown(() => fx.deleteSync(recursive: true));

  RemediateRun run({Map<String, String> extra = const {}}) {
    final res = Process.runSync('bash', [
      'scripts/release_drift_remediate.sh',
      'v1.2.3',
      bodyFile,
    ], environment: {
      'PATH': '$bin:${Platform.environment['PATH']}',
      'GITHUB_REPOSITORY': 'OWNER/REPO',
      'GH_TOKEN': 'stub',
      'GH_LOG_FILE': logPath,
      'GH_STUB_DIR': fx.path,
      ...extra,
    });
    return RemediateRun(
      res.exitCode,
      '${res.stdout}${res.stderr}',
      File(logPath).existsSync()
          ? File(logPath).readAsLinesSync()
          : const <String>[],
      File('${fx.path}/last-issue-body.md').existsSync()
          ? File('${fx.path}/last-issue-body.md').readAsStringSync()
          : null,
    );
  }

  List<String> logged(List<String> log, String needle) =>
      log.where((l) => l.contains(needle)).toList();

  test('missing remediate script fails the suite loudly', () {
    expect(File('scripts/release_drift_remediate.sh').existsSync(), isTrue,
        reason: 'scripts/release_drift_remediate.sh must exist (gh-2042 AC2)');
  });

  test('happy path: finds the tag run + provenance job, reruns it, files the drift issue', () {
    final r = run();
    expect(r.exitCode, 0, reason: r.out);
    final listCalls = logged(r.log, 'run list');
    expect(listCalls, hasLength(1));
    expect(listCalls.single, contains('--workflow ci.yml'));
    expect(listCalls.single, contains('--branch v1.2.3'));
    final jobsCalls = logged(r.log, 'actions/runs/123/jobs');
    expect(jobsCalls, hasLength(1));
    final reruns = logged(r.log, 'run rerun 123');
    expect(reruns, hasLength(1), reason: 'the re-request must happen');
    expect(reruns.single, contains('--job 77'),
        reason: 'the rerun targets the Sign release checksums JOB, '
            'not the whole run (a full rerun would re-attach assets the '
            'immutability gate then refuses)');
    expect(logged(r.log, 'issue create'), hasLength(1),
        reason: 'drift must page (an issue), not linger');
    expect(r.issueBody, isNotNull);
    expect(r.issueBody!, contains('v1.2.3'));
    expect(r.issueBody!, contains('fa-macos-arm64.tar.gz'),
        reason: 'the filed issue quotes the drift details');
    expect(r.issueBody!, contains('re-requested'),
        reason: 'the body records the auto-remediation');
  });

  test('an OPEN drift issue with the same tag → comment, never a duplicate issue', () {
    File('${fx.path}/open-issues.tsv').writeAsStringSync('13\t[release-drift] SHA256SUMS drift on v1.2.3\n');
    final r = run();
    expect(r.exitCode, 0, reason: r.out);
    expect(logged(r.log, 'issue create'), isEmpty);
    expect(logged(r.log, 'issue comment 13'), hasLength(1));
  });

  test('rerun request fails → the issue STILL pages, body names the failure', () {
    File('${fx.path}/rerun-fails').writeAsStringSync('');
    final r = run();
    expect(r.exitCode, 0, reason: r.out);
    expect(logged(r.log, 'issue create'), hasLength(1),
        reason: 'paging must not depend on the re-request succeeding');
    expect(r.issueBody!, contains('re-request FAILED'));
  });

  test('no completed tag run found → the issue still pages (re-request impossible)', () {
    File('${fx.path}/no-runs').writeAsStringSync('');
    final r = run();
    expect(r.exitCode, 0, reason: r.out);
    expect(logged(r.log, 'run rerun'), isEmpty);
    expect(logged(r.log, 'issue create'), hasLength(1));
    expect(r.issueBody!, contains('no completed'));
  });

  test('issue filing fails → exit 1 (the only total failure the step can own)', () {
    File('${fx.path}/no-runs').writeAsStringSync('');
    File('${fx.path}/issue-fails').writeAsStringSync('');
    final r = run();
    expect(r.exitCode, isNot(0), reason: r.out);
    expect(r.out, contains('::error::'));
  });
}

class RemediateRun {
  RemediateRun(this.exitCode, this.out, this.log, this.issueBody);
  final int exitCode;
  final String out;
  final List<String> log;
  final String? issueBody;
}

const String _ghStub = '''
#!/usr/bin/env bash
echo "\$*" >> "\$GH_LOG_FILE"
case "\$1 \$2" in
  "run list")
    if [ -f "\$GH_STUB_DIR/no-runs" ]; then canned='[]'; else canned='[{"databaseId": 123, "conclusion": "success"}, {"databaseId": 99, "conclusion": null}]'; fi
    # Emulate gh's --jq (the script filters server-side JSON through it).
    printf '%s' "\$canned" | jq '[.[] | select(.conclusion != null)] | first | .databaseId // 0'
    ;;
  "run rerun")
    if [ -f "\$GH_STUB_DIR/rerun-fails" ]; then
      echo "gh: rerun rejected (stub)" >&2
      exit 1
    fi
    ;;
  "api "*)
    if printf '%s' "\$*" | grep -q '/jobs'; then
      printf '%s' '{"jobs":[{"name":"Build native binaries","id":1},{"name":"Sign release checksums","id":77}]}' \\
        | jq '.jobs[] | select(.name == "Sign release checksums") | .id'
    fi
    ;;
  "issue "*)
    if [ "\$2" = "list" ]; then
      # Emulate gh's --json number,title + --jq title-match: answer the
      # number of an OPEN issue whose title matches --arg t exactly.
      if [ -f "\$GH_STUB_DIR/open-issues.tsv" ]; then
        want=""
        capture=0
        title=""
        for a in "\$@"; do
          if [ "\$capture" = "1" ]; then title="\$a"; capture=0; fi
          [ "\$prev" = "--arg" ] && [ "\$a" = "t" ] && capture=1
          prev="\$a"
        done
        awk -F '\\t' -v t="\$title" '\$2 == t { print \$1 }' "\$GH_STUB_DIR/open-issues.tsv"
      fi
      exit 0
    fi
    if [ "\$2" = "create" ]; then
      if [ -f "\$GH_STUB_DIR/issue-fails" ]; then
        echo "gh: issue create rejected (stub)" >&2
        exit 1
      fi
      while [ \$# -gt 0 ]; do
        if [ "\$1" = "--body-file" ]; then
          cp "\$2" "\$GH_STUB_DIR/last-issue-body.md"
        fi
        shift
      done
      echo "https://github.com/OWNER/REPO/issues/42"
      exit 0
    fi
    if [ "\$2" = "comment" ]; then
      if [ -f "\$GH_STUB_DIR/issue-fails" ]; then
        echo "gh: issue comment rejected (stub)" >&2
        exit 1
      fi
      while [ \$# -gt 0 ]; do
        if [ "\$1" = "--body-file" ]; then
          cp "\$2" "\$GH_STUB_DIR/last-issue-body.md"
        fi
        shift
      done
      exit 0
    fi
    ;;
esac
exit 0
''';

// gh-2042 — release asset immutability gate (scripts/release_asset_gate.sh).
//
// The v1.0.680 incident: the daily build-macos train re-attached fresh
// fa-macos-arm64 assets to the ALREADY-PUBLISHED release ~2-3h AFTER the
// signed SHA256SUMS was attached — the manifest never re-ran, and every
// `fa update` provenance check on the train failed. Contract (AC1): a
// PUBLISHED release is immutable for `fa-*` assets — a post-publish attach
// must skip already-attached assets, refuse unattached fa-* assets loudly,
// and still allow the non-fa clobber-refresh (store AAB/IPA/APK artifacts
// are deliberately not provenance-covered, scripts/release_required_assets.txt).
// Drafts (and missing releases — the caller creates the draft first) attach
// exactly as before.
//
// Behavioral coverage follows release_hygiene_test.dart's style: a stubbed
// `gh` on PATH answering from fixture files, every invocation logged.
import 'dart:io';

import 'package:test/test.dart';

import 'release_hygiene_test_support.dart';

void main() {
  GateRun runGate(
    String name, {
    String? releaseState,
    List<String> attachedNames = const [],
    List<String> assets = const ['fa-linux-x64.tar.gz'],
    List<String> viewSeq = const [],
  }) {
    final dir = Directory(
      '${hygieneFixtureRoot.path}/gate-$name-${DateTime.now().microsecondsSinceEpoch}',
    )..createSync(recursive: true);
    final bin = stubGh(dir.path);
    if (releaseState != null) {
      File('${dir.path}/release-state.txt').writeAsStringSync('$releaseState\n');
    }
    if (attachedNames.isNotEmpty) {
      File(
        '${dir.path}/asset-names.txt',
      ).writeAsStringSync('${attachedNames.join('\n')}\n');
    }
    if (viewSeq.isNotEmpty) {
      File('${dir.path}/view-seq.txt').writeAsStringSync(
        '${viewSeq.join('\n')}\n',
      );
    }
    for (final asset in assets) {
      File('${dir.path}/$asset').writeAsStringSync('bytes of $asset');
    }
    File('${dir.path}/log').writeAsStringSync('');
    final res = Process.runSync('bash', [
      File('scripts/release_asset_gate.sh').absolute.path,
      'v1.2.3',
      ...assets,
    ], environment: {
      'PATH': '$bin:${Platform.environment['PATH']}',
      'GITHUB_REPOSITORY': 'OWNER/REPO',
      'GH_STUB_DIR': dir.path,
      'GH_LOG_FILE': '${dir.path}/log',
      'GH_TOKEN': 'stub',
    });
    return GateRun(
      res.exitCode,
      '${res.stdout}${res.stderr}',
      File('${dir.path}/log').readAsLinesSync(),
    );
  }

  test('missing gate script fails the suite loudly', () {
    expect(File('scripts/release_asset_gate.sh').existsSync(), isTrue,
        reason: 'scripts/release_asset_gate.sh must exist (gh-2042 AC1)');
  });

  test('draft release → attach: every asset uploaded --clobber, exit 0', () {
    // Default fixture state (no release-state.txt) = draft: the pre-gate
    // behavior every existing release test pins must be untouched.
    final run = runGate('draft', assets: ['fa-linux-x64.tar.gz', 'a.zip']);
    expect(run.exitCode, 0, reason: run.out);
    expect(
      run.log,
      contains('release upload v1.2.3 fa-linux-x64.tar.gz --clobber --repo OWNER/REPO'),
    );
    expect(
      run.log,
      contains('release upload v1.2.3 a.zip --clobber --repo OWNER/REPO'),
    );
    expect(run.log.where((l) => l.contains('release edit')), isEmpty,
        reason: 'the gate never publishes — provenance owns the flip');
  });

  test('published release + fa-* NOT attached → loud refusal, NOTHING uploaded', () {
    // The v1.0.680 shape: re-attaching an unattached fa-* asset to a
    // published release invalidates the signed manifest. Refuse before any
    // upload — a red leg, never silent drift.
    final run = runGate('published-fa', releaseState: 'false',
        attachedNames: ['fa-web-spa.zip'], assets: ['fa-macos-arm64.tar.gz']);
    expect(run.exitCode, isNot(0), reason: run.out);
    expect(run.out, contains('::error::'));
    expect(run.out, contains('fa-macos-arm64.tar.gz'));
    expect(run.out.toLowerCase(), contains('published'),
        reason: 'the refusal must name the immutability contract');
    expect(
      run.log.where((l) => l.contains('release upload')),
      isEmpty,
      reason: 'a refused attach uploads nothing',
    );
    expect(run.log.where((l) => l.contains('release edit')), isEmpty);
  });

  test('published release + fa-* ALREADY attached → immutable skip, exit 0, no upload', () {
    // The release-twin binaries re-run: same tag commit, asset already on
    // the published release. Skip — rebuilding + clobbering would drift the
    // manifest for the minutes until provenance re-signs (and the re-request
    // is a job rerun away anyway).
    final run = runGate('published-skip', releaseState: 'false',
        attachedNames: ['fa-linux-x64.tar.gz', 'SHA256SUMS', 'SHA256SUMS.sig'],
        assets: ['fa-linux-x64.tar.gz']);
    expect(run.exitCode, 0, reason: run.out);
    expect(run.log.where((l) => l.contains('release upload')), isEmpty,
        reason: 'an already-attached asset on a published release is skipped');
    expect(run.log.where((l) => l.contains('release edit')), isEmpty);
    expect(run.out.toLowerCase(), contains('skip'));
  });

  test('published release + non-fa asset → clobber-refresh stays allowed', () {
    // Store artifacts (AAB/IPA/APK) and DMG refreshers are deliberately not
    // provenance-covered (release_required_assets.txt scope note) — the
    // daily mobile leg keeps refreshing them.
    final run = runGate('published-nonfa', releaseState: 'false',
